#include<bits/stdc++.h>
#define int long long
using namespace std;
signed main(){
	ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);
	string s;
	cin>>s;
	vector<int>v;
	int ans=0,mx=0;
	for(int i=0;i<s.size();i++){
		for(int j=mx;j+i<=s.size();j++){
			string x=s.substr(i,j);
			string y=x;
			reverse(x.begin(),x.end());
			if(x==y){
				v.push_back(j);
				mx=max(mx,j);
			}
		}
	}
	for(int i=0;i<v.size();i++){
		if(v[i]==mx){
			ans++;
		}
	}
	cout<<mx<<" "<<ans;
    return 0;
}
